# -*- coding: utf-8 -*-
T = {}
T['the_stair.txt'] = [
('r3a_bf_picnic', "A rug laid out in the grass, a basket with its lid on, and two cups, one chipped and one not. The loaf has been out so long it's become a geological feature. Whoever laid this out expected company at the foot of the Stair, and was patient about it. Both cups are the right way up, ready.", None),
('r3a_bf_signpost', "A signpost with three boards. The top one says UP, and underneath, smaller: (BURIED.) The next says GOATS, with an arrow and the word SCENIC. The lowest says THE RUINS, and then, in a different hand: PLEASE MIND THE DUMMY.", None),
('r3a_bf_firering', "A ring of stones round old ash, a burnt stick leaning in it. The ash still holds the shape of a very small fire. Whoever built it knew not to build it big, in case the Stair noticed.", None),
('r3a_bf_flask', "A dented flask lying in the grass with its cup screwed on tight. A name is scratched under the base: BARNABY. It rattles. Somebody has put a button in it for luck.", None),
('r3a_bf_names', "A flat stone with a column of names scratched into it: climbers who put their names down before they started up the Stair, just in case. Near the bottom, one has been crossed out and written again smaller: BERT (TURNED BACK). Beside it, in a bigger hand: BERT (WENT AGAIN).", None),
('r3a_sf_scope', "A brass telescope bolted to the last ledge, pointing back down the way you came. You put your eye to it. The whole valley lies there like a plate, with the Ruins no bigger than a thumbprint at the bottom. Something very small and wooden is walking in front of the door, to the end of its patch and back. It has never once looked up.", None),
('r3a_sf_cairn', "A little cairn at the top of the climb, built from stones that aren't from this ledge. Somebody carried each one up. A stick in the top has a ribbon on it, and the ribbon says nothing. It's just a ribbon. It's glad you made it.", None),
('r3a_sf_flask', "A flask wedged in a crack on the halfway ledge so the wind can't have it. A note is taped round it: FOR THE NEXT ONE. IT'S STILL TEA. You don't open it. You feel looked after anyway.", None),
('r3a_sf_cairn_low', "A cairn at the very bottom of the face, no higher than your knee. Every stone has one little line scratched on it, one for every climber who started. There are a lot of stones. Beside it is a much smaller pile, for the ones who got back down to say so.", None),
('r3a_sf_firering', "A cold fire ring on the bottom ledge, the print of a kettle still pressed in the ash. Somebody had a last hot drink here before the face. It looks like a very good decision.", None),
('r3a_sf_bert', "BERT WAS HERE. It's scratched in the rock at the height of a hand reaching up. Under it, smaller, an arrow pointing UP. Under that, smaller still, an arrow pointing down, with a question mark.", None),
]
T['mount_vigil.txt'] = [
('r3a_ce_cord', "A coil of rope left on the floor, a paper tag knotted on: CORD, ONE OF THREE. DON'T UNTIE. DON'T TRIP. -- B. The other end of it runs away across the cave, looped round every stalagmite it passes, like someone leading a very patient dog.", None),
('r3a_ce_flask', "A flask frozen to the floor, its cup welded to the lid. It sloshes a little in the middle. It's the sort of tea that has waited so long it's turned into an opinion.", None),
('r3a_ce_caps', "Pale toadstools crowding a crack in the rock, lit faintly from inside, the colour of a very old bruise on the moon. You don't know if they're safe. They don't look like they're on anybody's menu.", None),
('r3a_ce_boots', "A pair of boots standing side by side against the wall, toes together, laces neatly tucked in. Whoever left them stepped out of them and went on, in their socks, in this. You decide they were being brave about it.", None),
('r3a_ce_pool', "A pool the size of a plate, caught under a drip. Each drip lands with a note, and the cave hands the note back half a second late and a little flat. You wait for the next one. It's very satisfying.", None),
('r3a_cg_slab', "A flat slab of rock, worn smooth and shiny by hands. You lay your own hand on it. The whole stone is humming, one low note, in the heel of your palm, as if it's been waiting a long time for somebody to ask.", None),
('r3a_cg_slate', "A slate on a stick, in chalk: THE GALLERY IS IN D. (SLIGHTLY FLAT.) PLEASE DON'T WHISTLE. -- THE MANAGEMENT. Under it someone has added: WHO IS THE MANAGEMENT. And after a bit, in a smaller hand: ME. SORRY.", None),
('r3a_cg_tea', "A little spirit stove on a flat stone, a blackened kettle, two tin cups. Somebody meant to make tea in the one place in the world where the kettle would sing along with the walls. It's all still tidy. The matches are in a tin with a lid, and the lid says DRY.", None),
('r3a_cg_bedroll', "A bedroll frozen into the shape of whoever slept in it: a long dent where they lay, a smaller dent where their hat went. They came to sleep inside the singing rock. You can think of worse nights.", None),
('r3a_cg_scratch', "Scratched into the wall at head height, in letters shakier than the rock: PLEASE DON'T WHISTLE. IT WHISTLES BACK. -- B. Underneath, in someone else's hand: IT WHISTLED BACK. WE HAD A TALK.", None),
('r3a_cg_caps', "A clump of pale toadstools in the lee of a stalagmite, lit from inside. They sway very slightly, though there's no wind, in time with the hum. That is not mushroom behaviour. You nod politely and keep your hands to yourself.", None),
]
T['upper_vigil.txt'] = [
('r3a_hut_shelf', "A shelf of oil tins and lamp wicks, every label in the same neat hand. The last tin is only half-labelled: OIL. And then the pen simply stops, as if it was called away to light something.", "{thoughtful}Somebody always means to finish the label."),
('r3a_hut_table', "A small round table with two mugs on it, a candle stub, and a hand of cards laid face down. One mug is turned to face the empty chair. The other is turned to face the door.", "{sly}They were waiting for someone, and they brought cards in case it took a while. Good sense."),
('r3a_hut_window', "A little window, frosted over in ferns. The only clear bit is a circle at about the height of a child's nose. Somebody has stood here breathing on the glass, looking for a lamp along the ridge.", "{smile}That's what a window's for. Looking for people."),
('r3a_hut_roster', "A chalk slate on a post: THE ROUND. Under it, a column of lamp numbers, each with a tick, down to number thirty-one. Thirty-two has a question mark. Thirty-three to forty are just numbers, waiting.", "{bored}Thirty-one out of forty. I've seen worse attendance at a chapel."),
('r3a_hut_kindling', "A bundle of kindling stacked beside the cold hearth, tied with a bow. A tag on the string: FOR WHOEVER COMES NEXT. Under it, smaller: (TIED, NOT TIED TIGHT.)", "{smile}That's rather kind. I don't like it. It's too kind to argue with."),
('r3a_su_tin', "A tin box wedged into a heap of rocks at the top of the world, a pencil on a string. Inside is a notebook: the summit register. Names, dates, one-word remarks. VIEW. WIND. VIEW. WIND. COLD. VIEW. A page has been torn out near the front, with a note in its place: I WAS GOING TO WRITE SOMETHING PROFOUND. IT WAS TOO WINDY.", "{bored}I'm not signing it. I'd have to write 'wind', and I've got more to say about it than that."),
('r3a_su_snowman', "A very small snowman at the very top, stone eyes, a stick for each arm. Somebody carried snow up a mountain made of snow to build him. One stick arm has been turned to point at the way down.", "{smile}He's the only one up here with the right idea."),
('r3a_su_hat', "A last stake in the snow, a woolly hat on it, and a card: LOST HERO'S HAT. APPLY WITHIN. Under it, in the same round hand, a note added later: (OKAY. WE'RE GIVING UP. KEEP IT. WE'LL GET ANOTHER.)", "{sly}Somebody has put a great many stakes into a mountain over one hat."),
]
T['ice_caves.txt'] = [
('r3a_it_caps', "Pale toadstools in a crack, glowing. Their light isn't blue like the crystals: it's a thin, milky green, like the dial of a watch. A line of tiny prints leads away from them. Something has been eating, politely, one cap at a time.", "{bored}If it's glowing and something's nibbling it, it's probably fine. Probably."),
('r3a_it_bedroll', "A bedroll laid out flat in a dry corner, a rolled coat for a pillow, and a pair of socks hung on a stalagmite to dry. They have been dry for a long time. A tag pinned to the pillow: BERT'S. DON'T.", "{sly}'Don't.' Not even 'please'. He means it."),
('r3a_it_tea', "A tea kit on a flat stone: spirit stove, kettle, two cups. One cup has BERT scratched into the side. The other says GUEST.", "{smile}I like him. I haven't met him, and I like him."),
('r3a_it_slate', "A slate stuck in the floor: NEXT CAMP: THE GROTTO. TEA'S ON IF THE GOBLIN'S IN. THE GOBLIN IS ALWAYS IN. THE TEA IS NOT ALWAYS ON. -- B.", "{bored}A map for people who like surprises."),
('r3a_ig_slate', "A slate beside the stall: PRICES. 1 GOLD = 1 GOLD. NO HAGGLING. (HAGGLING = 2 GOLD.) Someone has chalked a little arrow pointing at the goblin, and: SHE MEANS IT.", "{sly}I'd haggle. I'd lose, though. I can tell."),
('r3a_ig_boots', "A heap of single boots with a tag chalked on the top one: BOOTS, SECOND-HAND, NO PAIRS. (THEY WERE ALL LEFT LIKE THIS.) And it's true. A left in a lovely red, a right with a hole in the toe, three of the same left foot.", "{thoughtful}That's a lot of people who walked off the mountain with half their boots."),
('r3a_ig_tea', "A tea kit on a ledge near the stall: stove, kettle, two cups. The kettle is warm. Nobody is near it. A card is propped against it: ON. HELP YOURSELF. LEAVE A BISCUIT. -- B.", "{smile}...Do we have a biscuit?"),
('r3a_ig_caps', "Pale toadstools by the wall, fat and glowing. A tiny hand-lettered sign has been stuck beside them on a toothpick. It says: NO.", "{sly}'No.' It's a clear, strong policy."),
('r3a_ig_pool', "A pool the size of a plate under a drip. The drip lands, and the grotto sends the note back a heartbeat late. One coin lies on the bottom, green with cold, wished at. It hasn't worked. It's still a very good puddle.", "{thoughtful}I'd wish for a warmer cave. Then I'd feel silly."),
('r3a_ih_caps', "Pale toadstools climbing a stalagmite in a tidy spiral, like a small staircase for something that isn't here yet.", "{awed}It's almost pretty. I hate that it's pretty."),
('r3a_ih_slate', "A slate by the corner where the golems stand: MIND THE GOLEMS. THEY LOOK LIKE ROCKS. SO DO ROCKS. (THE ROCKS DON'T HIT BACK.)", "{bored}That's less a warning than a riddle."),
('r3a_ih_tea', "A tea kit tucked out of the way, stove cold, two cups upside down on a cloth. A note: GONE ON. BACK BY DARK. TEA'S IN THE TIN. -- B.", "{smile}He keeps saying he'll be back by dark. There isn't any dark here. It's all dark."),
('r3a_ih_bedroll', "A bedroll rolled neatly and tied with a cord, a coat for a pillow, and one sock hung alone on a stalagmite like a very small flag. The tag says: BERT'S. STILL.", "{sly}'Still.' So he means to come back for it."),
('r3a_ih_fall', "A frozen fall on the wall, a sheet of ice that was running when the cold came and never finished. The glow behind it puts a tiny rainbow in the stone, but only if you stand exactly here.", "{awed}Stand still. I want to look at it a bit longer."),
('r3a_ir_guano', "A heap of bat leavings, deep and old, with a dent in the top where something sat down to think. You'd need a ladder to say anything rude about it.", "{bored}No. We're not going to talk about it."),
('r3a_ir_census', "A slate: BAT CENSUS. A column of tally marks, crossed out, redone, crossed out. At the bottom: ABOUT 40. (THEY WON'T HOLD STILL.)", "{sly}Forty and a bit. I'd have put 'a lot'."),
('r3a_ir_caps', "Pale toadstools in a crevice, glowing against the dark. A bat hangs above them with its wings folded round itself like a coat, pretending not to watch the mushrooms.", "{thoughtful}It's guarding them. Or it's very shy about its lunch."),
('r3a_ir_claws', "Deep scratches in the rock, a hand-span apart, all running the same way. No bat made those. Something far bigger has come through here, and gone up the passage you're about to take. Or down it. Hard to tell.", "{worried}Those are higher up than I'd like them to be."),
]
T['heralds_rest.txt'] = [
('r3a_hl_banner', "A banner across the wall: WELCOME, HERO. It's been repainted so many times the lettering has gone lumpy: the W has a bump, the O has a second O trying to be born. A small card is pinned in one corner: REPAINTED (11TH). NEXT REPAINT: ON ARRIVAL.", "{thoughtful}Eleven repaints. That's a lot of waiting to put on one wall."),
('r3a_hl_statue', "A statue under a bedsheet, tied at the neck with a red ribbon. A card pinned to it: UNVEIL ON ARRIVAL. There's a line of dust along the top of the sheet and a yellow ring where the ribbon sits. Whoever's under there has been waiting patiently, with no face, in the dark.", "{sly}I'd peek. But somebody has been very serious about the ribbon."),
('r3a_hl_chair', "A chair under a dust sheet with a small tag on it: SAVED. The sheet has been lifted and put back so often it's fitted itself to the chair like a second skin.", "{bored}I wonder who it's saved for. And whether they'd sit still."),
('r3a_hl_bowl', "A wooden bowl of paper slips under a card: SUGGESTIONS FOR THE HERO'S WELCOME. You read a few. MORE CHAIRS. LESS SINGING. SOUP. WHAT IF THEY'RE SHY. ASK THEM WHAT THEY WANT. (THEN DO IT.) That last one has been underlined twice.", "{smile}Whoever wrote the last one has the right idea."),
('r3a_hl_board', "A chalk board of arrivals, two columns: DATE and WHO. The DATE column is full, back and back and back. The WHO column is a row of neat blanks, one beside every date, because the herald is an optimist. Today's has been left blank in the nicest possible way.", "{bored}'Nobody' has a lot of dates."),
('r3a_st_cheese', "A stack of cheese wheels with a wedge cut out of the top one. A sign: HERALD'S HARD. FOR TRAVELLERS, AND FOR PROPPING DOORS.", "{bored}A cheese you can wedge a door with. That's a recommendation, I think."),
('r3a_st_scales', "A set of brass scales at the end of the counter, a loaf in one pan, a weight in the other. The loaf pan sits lower. It's always the loaf pan. The shopkeeper has stopped looking.", "{sly}Nobody checks the scales. That's the secret of this village."),
('r3a_st_rope', "Hanks of rope on pegs, every size and colour. A card on the biggest: NOT FOR SALE. THIS IS THE LAST ROPE. I'VE BEEN SAVING IT. Underneath: (FOR WHAT, I'D LOVE TO KNOW.)", "{thoughtful}Saving rope for an emergency. In a shop that sells rope. Hm."),
('r3a_st_hams', "Four smoked hams on hooks along a rail, each with a tag in the shopkeeper's loopy hand. They say PAULINE, DOREEN, ONE FOR THE HERO, and, on the fourth: DON'T ASK.", "{bored}I'm not asking. Not asking is my favourite way to eat."),
('r3a_st_flour', "A sack of flour, open, a scoop standing up in it. A line of tiny floury footprints leads from the sack, under the counter and out of sight. Something small has been very thorough about not being seen.", "{smile}The shop mouse. I'd like to buy some of that confidence."),
('r3a_st_slate', "A chalk slate at the counter: TODAY: SOUP-TINS, 2 FOR 3 (NOT HALF OFF.) ALSO TODAY: PLEASE STOP ASKING IF THE ROPE'S FOR SALE.", "{sly}It's the rope, isn't it. It's always the rope."),
('r3a_fg_bellows', "Bellows with a patched leather belly, hung by the hearth, the nozzle pointing into the coals. Somebody has chalked a tally on the handle: 14,000 pumps. It's gone round onto the second handle.", "{bored}I'd count something else. Anything else."),
('r3a_fg_blades', "A rack of blades with no edge yet, hilts on, point-down like a row of very serious cutlery. Each has a tag tied to the hilt, with a name: not a person's name. GALE. THAW. DRIZZLE. WHAT NOW.", "{sly}I want to be called Drizzle."),
('r3a_fg_shoes', "Horseshoes on nails, open end up so the luck can't run out. A card: PLEASE DO NOT TELL THE HORSE. There's no horse in the village. You wonder how long it's been a joke, and whether the joke is the horse.", "{bored}Don't tell the horse. Understood."),
('r3a_fg_tongs', "Tongs of every size and a few hammers, each hung in its own painted outline on the board, so you'd know at once if one went missing. The outline for the biggest hammer is empty. A card: THE SMITH HAS IT.", "{thoughtful}'The smith has it.' That does seem like a safe place for a hammer."),
('r3a_fg_tub', "A barrel of black water for quenching, a ladle hooked on its side, an oil skin on top that shows you a small rainbow of the room. When something hot goes in, it hisses. The lid has a hiss-shaped scorch mark on it.", "{thoughtful}Put something hot in and it comes out better. I don't think that works on people."),
('r3a_fg_coal', "A heap of coal with a shovel standing in it, and a nest of coal dust pressed into the shape of a cat. No cat.", "{bored}A cat-shaped absence. Very forge."),
('r3a_fg_stone', "A grindstone in its trough of water, the wheel glinting. A word is carved into the frame, over and over, in different hands: SHARPER. SHARPER. SHARPER. It's either an instruction or a prayer.", "{sly}It's a threat, and it's aimed at the blades."),
('r3a_bt_doves', "A dovecote on a post, one grey dove peering from the door with the look of a bird who's been woken for something dull. A tag on the post: RESIDENT. (ASKED.) Another underneath: PLEASE DON'T RING THE BELL WHILE SHE'S HOME.", "{smile}A tenant with boundaries."),
('r3a_bt_cleat', "The bell rope coiled on its cleat at the foot, a tuft of red wool tied on where hands go. The wool is worn flat. A hundred years of people thinking about ringing it, and some of them doing it.", "{thoughtful}It's polite. It gives you something to hold on to."),
('r3a_bt_tea', "A ringer's tea corner: a spirit stove, a kettle, two cups, a biscuit tin with a lid that says ONE EACH. Inside, one biscuit. Someone has been very good, or very busy.", "{bored}'One each.' So there's a person in this village who counts biscuits. I'd like to avoid them."),
('r3a_bt_slate', "A slate at the foot of the stair: THE BELL IS NOT A SNOOZE BUTTON. -- MGMT. Underneath, in another hand: IT'S A LITTLE BIT A SNOOZE BUTTON.", "{sly}It's a snooze button for the whole valley."),
('r3a_bt_flask', "A flask propped on a ledge, wearing a knitted cosy that someone has taken a great deal of time over. It has a face.", "{smile}It's got ears. I want one."),
('r3a_bt_rope', "Spare bell rope in loops on pegs: one for a calm day, one for a high wind, and a short, thick one labelled: FOR IF THE BELL GETS CROSS.", "{bored}If the bell gets cross. Of course."),
('r3a_bt_slit1', "An arrow slit with a view straight down the village: roofs like little tin lids, smoke going straight up in the still air. Someone is hanging washing on the line across the middle. From up here they look like a thought somebody had.", None),
('r3a_bt_slit2', "The other slit looks out at the mountain, and the mountain looks back, much larger. A chough sits on the sill with a snowflake on its head. It doesn't seem to mind it, or you.", "{awed}It looks like it's about to say something, doesn't it?"),
('r3a_bt_geranium', "A geranium in a clay pot on the floor, doing very well in a tower with no sun. A card stuck in the soil: PLEASE DO NOT TELL THE INN. (THEY'D WANT IT BACK.)", "{bored}This village runs on secret geraniums."),
('r3a_ma_loom', "A tall loom taking up most of the wall, a half-finished scarf on it. The scarf is already longer than the room. It runs out of the window and, if you follow it with your eye, away down the street, over the roofs and into the snow, and out of sight. So the loom does exist. It's a very good loom.", "{awed}How long is that scarf?"),
('r3a_ma_wheel', "A spinning wheel with a puff of grey wool on the distaff, the treadle worn into a smooth shallow dip. A stool beside it, with a cushion in the shape of its sitter. The wool keeps trying to drift off and keeps being tucked back.", "{thoughtful}It's like watching someone mind a very small cloud."),
('r3a_ma_basket', "A basket of wool balls with the needles stuck in mid-row, as if the knitter had to answer the door and will be right back. The row is long. The moment has also been long.", "{bored}Don't touch it. I know the look of 'mid-row'."),
('r3a_ma_window', "A frosted window with a clear circle breathed into the middle, at exactly the height of a knitter watching the road. A sprig of heather is stuck in the frame, nearly dry, nearly still blue.", "{smile}The sort of window you look out of while you pretend you aren't."),
('r3a_ma_balls', "Balls of wool spilled across the floor in red and blue and gold, trailing threads. One thread leads under the bed. Something has been hunting it, and it has been hunting back.", "{sly}The hare. It's always the hare."),
('r3a_po_buns', "A tray of buns cooling under a cloth with one corner flipped back. Three buns, steaming. One has a very small, very careful bite taken out of it, from someone about this high. The cloth has been put back to look innocent.", "{sly}I know that bite. I did that bite."),
('r3a_po_flour', "A sack of flour with a scoop in it and a handprint on the side. A small one. It's been pressed quite thoroughly, as if to check it was real.", "{bored}Another culprit. I'd say it's the same one."),
('r3a_po_bird', "A finch in a brass cage, round as a bun, regarding the buns with great interest. A tag on the cage: CRUMB. DO NOT FEED CRUMB. (CRUMB IS A LIAR. CRUMB HAS ALREADY BEEN FED.)", "{smile}I believe every word on that tag."),
('r3a_po_geranium', "A red geranium in a pot on the sill, blooming in the sort of heat only a bakery has. A note on a stick: PLEASE DO NOT TELL THE TOWER.", "{bored}There's a theme in this village."),
('r3a_po_window', "A window steamed solid on the inside. Someone has drawn a bun on it with a finger, and a smile on the bun. It's dripping now. The bun is crying a bit.", "{smile}Poor bun."),
('r3a_po_scales', "Scales with a lump of dough on one side and an exact weight on the other. They're balanced. A mark chalked on the beam: PERFECT. Under it, smaller: (ONCE.)", "{sly}They won't balance for us, will they."),
('r3a_po_slate', "A slate by the door: TODAY: BUNS. TOMORROW: BUNS. (CHANGE ON REQUEST.) Underneath, in different chalk: THERE'S NEVER A REQUEST.", "{bored}Bold menu. I'd put 'surprise' if I wanted to sound optimistic."),
('r3a_ch_box', "A donation box with a slot and a chalk label: FOR THE HERO'S COMING-HOME. You peer through the slot. Buttons, mostly, and two lucky stones, and a pressed flower that's long since stopped being any colour.", "{thoughtful}Buttons. That's a lot of people with nothing left to give but buttons, giving them."),
('r3a_ch_bowl', "A bowl of folded paper slips beside the door, under a card: WISHES. You don't unfold any. One sticks out, and you read it before you can stop yourself: COME SOON. The next one says COME SOON, PLEASE. The one after: BRING SOUP.", "{smile}I like the last one best. It's the only one that's practical."),
('r3a_ch_hymnals', "A stack of hymnals with a candle stub on top, a ribbon marking the place in each. All the ribbons are in the same page. It's the one with the shortest verse.", "{sly}Efficient."),
('r3a_ch_geranium', "A geranium on the sill by the left window, red as a stop-sign. Somebody waters it before they pray, and if the soil is anything to go by, they've started praying a lot.", "{bored}Don't look at me. I'm not the one who waters."),
('r3a_ch_kneeler', "A knee cushion worn flat in the middle, its tassels gone, a neat patch on one corner. It's been knelt on a very long time by people who all had the same bad knee.", "{sly}Nobody warned them about the floor."),
]

base = 'c:/Users/clanc/Documents/Nobodys Hero/text/interactions/'
for fn, items in T.items():
    path = base + fn
    s = open(path, encoding='utf8').read()
    if '[%s]' % items[0][0] in s:
        print('skip', fn)
        continue
    out = ['\n# === ROUND 3, THE FUN CHECK (15 November 2026): chapters 1 and 2, the dullest rooms ===\n']
    for sid, txt, ves in items:
        out.append('# (draft)\n[%s]\n%s\n' % (sid, txt))
        if ves:
            out.append('# (draft)\n[%s_ves]\n%s\n' % (sid, ves))
    out.append('# === END ROUND 3 (chapters 1 and 2) ===\n')
    if not s.endswith('\n'):
        s += '\n'
    open(path, 'w', encoding='utf8').write(s + '\n'.join(out))
    print('wrote', fn, len(items))
